[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "music-player-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "music-player-surface",
      "components": [
        {
          "id": "root",
          "component": "Card",
          "properties": {
            "children": [
              "mainColumn"
            ]
          }
        },
        {
          "id": "mainColumn",
          "component": "Column",
          "properties": {
            "padding": {
              "all": 16
            },
            "spacing": 16,
            "children": [
              "albumArt",
              "songInfo",
              "progressControls",
              "playbackButtons",
              "volumeControls"
            ]
          }
        },
        {
          "id": "albumArt",
          "component": "Image",
          "properties": {
            "path": "/placeholder_album_art.png",
            "contentDescription": "Album Art for Echoes of Silence by Lumina",
            "aspectRatio": 1
          }
        },
        {
          "id": "songInfo",
          "component": "Column",
          "properties": {
            "spacing": 4,
            "horizontalAlignment": "center",
            "children": [
              "songTitle",
              "artistName"
            ]
          }
        },
        {
          "id": "songTitle",
          "component": "Text",
          "properties": {
            "text": "Echoes of Silence",
            "style": "headline-small"
          }
        },
        {
          "id": "artistName",
          "component": "Text",
          "properties": {
            "text": "Lumina",
            "style": "body-medium"
          }
        },
        {
          "id": "progressControls",
          "component": "Column",
          "properties": {
            "children": [
              "progressBar",
              "progressText"
            ]
          }
        },
        {
          "id": "progressBar",
          "component": "Slider",
          "properties": {
            "value": 37,
            "readOnly": true
          }
        },
        {
          "id": "progressText",
          "component": "Text",
          "properties": {
            "text": "1:24 / 3:45",
            "style": "label-medium",
            "horizontalAlignment": "center"
          }
        },
        {
          "id": "playbackButtons",
          "component": "Row",
          "properties": {
            "mainAxisAlignment": "space-evenly",
            "crossAxisAlignment": "center",
            "children": [
              "shuffleButton",
              "prevButton",
              "pauseButton",
              "nextButton",
              "repeatButton"
            ]
          }
        },
        {
          "id": "shuffleButton",
          "component": "Button",
          "properties": {
            "icon": "shuffle",
            "style": "filled-tonal",
            "contentDescription": "Shuffle (Active)"
          }
        },
        {
          "id": "prevButton",
          "component": "Button",
          "properties": {
            "icon": "skip_previous",
            "style": "icon",
            "contentDescription": "Previous Track"
          }
        },
        {
          "id": "pauseButton",
          "component": "Button",
          "properties": {
            "icon": "pause",
            "style": "filled",
            "contentDescription": "Pause"
          }
        },
        {
          "id": "nextButton",
          "component": "Button",
          "properties": {
            "icon": "skip_next",
            "style": "icon",
            "contentDescription": "Next Track"
          }
        },
        {
          "id": "repeatButton",
          "component": "Button",
          "properties": {
            "icon": "repeat",
            "style": "icon",
            "contentDescription": "Repeat"
          }
        },
        {
          "id": "volumeControls",
          "component": "Row",
          "properties": {
            "spacing": 8,
            "crossAxisAlignment": "center",
            "children": [
              "volumeIcon",
              "volumeSlider",
              "volumeText"
            ]
          }
        },
        {
          "id": "volumeIcon",
          "component": "Icon",
          "properties": {
            "name": "volume_up"
          }
        },
        {
          "id": "volumeSlider",
          "component": "Slider",
          "properties": {
            "value": 70,
            "flex": 1
          }
        },
        {
          "id": "volumeText",
          "component": "Text",
          "properties": {
            "text": "70%",
            "style": "label-medium"
          }
        }
      ]
    }
  }
]
